# frozen_string_literal: true

Object.send(:native_module, :Fcntl)

# `require "fcntl"`: the names of the fcntl(2) commands and the flags
# they carry. The module is a table and nothing else; the calls that use
# it are IO's own. Generated by `zr-dev gen tables` from ruby's Fcntl.
module Fcntl
  VERSION = "1.3.0"

  # The fcntl(2) commands, of which POSIX numbers the first five.
  F_GETFD = 1
  F_SETFD = 2
  F_GETFL = 3
  F_SETFL = 4

  # The one flag F_SETFD carries.
  FD_CLOEXEC = 1

  # The access modes of open(2), and the mask that reads them back.
  O_RDONLY = 67108864
  O_WRONLY = 268435456
  O_RDWR = 335544320
  O_ACCMODE = 503316480

  # The status flags, each a bit of its own. O_NDELAY is the older
  # spelling of O_NONBLOCK and names the same bit.
  O_APPEND = 1
  O_CREAT = 4096
  O_EXCL = 16384
  O_TRUNC = 32768
  O_NONBLOCK = 4
  O_NOCTTY = 0
end
